// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, uint8 _adminPk) public {
        // Use a private key to derive an EOA that is NOT the test contract's default msg.sender
        address admin = vm.addr(uint256(_adminPk) + 1);
        vm.assume(admin != address(this) && admin != tx.origin);
        vm.assume(_owner != tx.origin);
        // Ensure admin is the contract admin (constructor sets admin = payable(msg.sender))
        // Deploy a fresh C with admin as the caller
        vm.prank(admin);
        C c2 = new C();
        // Call setOwner as admin
        vm.prank(admin);
        c2.setOwner(_owner);
        // Assert: owner must equal _owner (reference behaviour)
        // The bug sets owner = tx.origin (the original caller of the test, not admin)
        assertTrue(c2.owner() == _owner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) {
            assertEq(c.owner(), caller == address(uint160(c.owner())) ? newOwner : c.owner());
        } catch {
            assertEq(c.owner(), c.owner());
        }
    }
}
